import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Text","description":"","frontmatter":{},"headers":[],"relativePath":"components/text.md","filePath":"components/text.md"}'),r={name:"components/text.md"};function n(c,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h1><p>Text is text in one of the nine type roles of the <a href="./../tokens">tokens</a>.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for every piece of interface text outside a control: titles, paragraphs, captions, labels, values. The role sets the size, leading, tracking, weight and element: <code>title</code> and <code>h1</code> are an h1, <code>h2</code> an h2, <code>body</code> and <code>prose</code> a p, and the rest a span shown as a block. Long text written as HTML goes in a <a href="./prose">Prose</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>role</code></td><td><code>body</code></td><td>One of the nine type roles</td></tr><tr><td><code>as</code></td><td></td><td>Another element (<code>a</code>, <code>label</code>, <code>dt</code>, <code>dd</code> …)</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>One line and an ellipsis; the full text on hover</td></tr><tr><td><code>lines</code></td><td></td><td><code>2</code>: two lines and an ellipsis</td></tr><tr><td><code>wrap</code></td><td><code>false</code></td><td>Keeps line breaks and wraps long words</td></tr><tr><td><code>muted</code></td><td><code>false</code></td><td>The muted text color</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The monospace font, at the role&#39;s size</td></tr><tr><td><code>tabular</code></td><td><code>false</code></td><td>Figures of equal width</td></tr><tr><td><code>href</code></td><td></td><td>The target, with <code>as=&quot;a&quot;</code></td></tr><tr><td><code>for</code></td><td></td><td>The labelled control, with <code>as=&quot;label&quot;</code></td></tr><tr><td><code>id</code></td><td></td><td>The element&#39;s id</td></tr><tr><td><code>children</code></td><td></td><td>The text</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Text has no margin and keeps its full line box, so its distance to its neighbours is the gap of a Stack or Row plus its leading. It is trimmed to its ink in three places only: inside a component that declares its height (and there it stays on one line), at the inner edge of a container, and next to a line. A link made with <code>as=&quot;a&quot;</code> keeps the color of the text around it and is underlined on hover.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/text/" title="Text" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/text/" target="_blank" rel="noopener">Text</a></figcaption></figure>',10)])])}const u=t(r,[["render",n]]);export{f as __pageData,u as default};
